<script setup lang="ts">export type InvoiceLine={description:string;quantity:number;unitPrice:number};const p=withDefaults(defineProps<{number:string;issuer:string;customer:string;date:string;dueDate?:string;currency?:string;lines:InvoiceLine[];status?:string}>(),{currency:'USD'});const money=(n:number)=>new Intl.NumberFormat(undefined,{style:'currency',currency:p.currency}).format(n)</script><template><article class="vx-invoice"><header><h2>Invoice</h2><span>{{number}}</span></header><div class="vx-invoice__parties"><div><strong>From</strong><p>{{issuer}}</p></div><div><strong>Bill to</strong><p>{{customer}}</p></div></div><p>Issued: {{date}} <span v-if="dueDate"> · Due: {{dueDate}}</span> <span v-if="status"> · {{status}}</span></p><div class="vx-data__scroll"><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody><tr v-for="(line,i) in lines" :key="i"><td>{{line.description}}</td><td>{{line.quantity}}</td><td>{{money(line.unitPrice)}}</td><td>{{money(line.quantity*line.unitPrice)}}</td></tr></tbody></table></div><div class="vx-commerce-total vx-commerce-line"><strong>Total</strong><strong>{{money(lines.reduce((a,l)=>a+l.quantity*l.unitPrice,0))}}</strong></div></article></template>
